	// Reads every settings row from an INI through a reader with GetBool/GetInt/GetFloat/GetString/GetPool.
	template <class Reader>
	void ReadSettings(const Reader& a_ini, Settings& a_out)
	{
		a_out.radio_iToggleKey = std::clamp<std::int32_t>(a_ini.GetInt("Radio", "iToggleKey", a_out.radio_iToggleKey), 1, 255);
		a_out.radio_fVolume = std::clamp(a_ini.GetFloat("Radio", "fVolume", a_out.radio_fVolume), 0.0f, 2.0f);
		a_out.radio_fSongIntroChance = std::clamp(a_ini.GetFloat("Radio", "fSongIntroChance", a_out.radio_fSongIntroChance), 0.0f, 1.0f);
		a_out.radio_iNewsEverySongs = std::clamp<std::int32_t>(a_ini.GetInt("Radio", "iNewsEverySongs", a_out.radio_iNewsEverySongs), 0, 50);
		a_out.radio_bGreetOnSwitchOn = a_ini.GetBool("Radio", "bGreetOnSwitchOn", a_out.radio_bGreetOnSwitchOn);
		a_out.music_fVolume = std::clamp(a_ini.GetFloat("Music", "fVolume", a_out.music_fVolume), 0.0f, 2.0f);
		a_out.music_fCrossfadeSeconds = std::clamp(a_ini.GetFloat("Music", "fCrossfadeSeconds", a_out.music_fCrossfadeSeconds), 0.0f, 10.0f);
		a_out.music_iDayStartHour = std::clamp<std::int32_t>(a_ini.GetInt("Music", "iDayStartHour", a_out.music_iDayStartHour), 0, 23);
		a_out.music_iNightStartHour = std::clamp<std::int32_t>(a_ini.GetInt("Music", "iNightStartHour", a_out.music_iNightStartHour), 0, 23);
		a_out.music_sUnknownLoopPool = a_ini.GetPool("Music", "sUnknownLoopPool", a_out.music_sUnknownLoopPool);
		a_out.music_sUnknownOncePool = a_ini.GetPool("Music", "sUnknownOncePool", a_out.music_sUnknownOncePool);
		a_out.music_bQuietWhenUnfocused = a_ini.GetBool("Music", "bQuietWhenUnfocused", a_out.music_bQuietWhenUnfocused);
		a_out.paths_sFalloutNVPath = a_ini.GetString("Paths", "sFalloutNVPath", a_out.paths_sFalloutNVPath);
		a_out.debug_bVerboseLog = a_ini.GetBool("Debug", "bVerboseLog", a_out.debug_bVerboseLog);
	}
